import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.D1JEzK2q.js";const g=JSON.parse('{"title":"Connect a channel","description":"","frontmatter":{},"headers":[],"relativePath":"guide/channels.md","filePath":"guide/channels.md"}'),s={name:"guide/channels.md"};function o(r,e,l,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="connect-a-channel" tabindex="-1">Connect a channel <a class="header-anchor" href="#connect-a-channel" aria-label="Permalink to &quot;Connect a channel&quot;">​</a></h1><p>Each agent can connect to multiple channels. A working connection still needs gateway access approval: transport delivery and pairing are separate checks.</p><h2 id="connect-telegram-or-discord" tabindex="-1">Connect Telegram or Discord <a class="header-anchor" href="#connect-telegram-or-discord" aria-label="Permalink to &quot;Connect Telegram or Discord&quot;">​</a></h2><p>Run the update wizard for an existing agent:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span></span></code></pre></div><p>Choose the channel connection step and provide the bot credentials. The wizard also supports updating or disconnecting Telegram, Discord, LINE, and Slack. Keep credentials in your local configuration or environment files.</p><p>For Telegram or Discord, message the bot privately, then review and approve the resulting request:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channels</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pending</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --channel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telegram</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channels</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> approve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --channel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telegram</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR_CODE</span></span></code></pre></div><p>Use <code>--channel discord</code> for Discord. Approve only a request you recognize. Verify success by sending another private message and receiving a reply.</p><h2 id="check-platform-delivery" tabindex="-1">Check platform delivery <a class="header-anchor" href="#check-platform-delivery" aria-label="Permalink to &quot;Check platform delivery&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Channel</th><th>Connection requirement</th><th>First thing to check when silent</th></tr></thead><tbody><tr><td>Telegram</td><td>Bot token; one long-polling receiver per token</td><td>Pairing approval; another poller causes <code>409 Conflict</code></td></tr><tr><td>Discord</td><td>Bot token and Message Content Intent</td><td>Intent enabled; View Channel, Read Message History, Send Messages permissions</td></tr><tr><td>LINE</td><td>Access token, channel secret, reachable webhook</td><td>Raw request body preserved for signature verification</td></tr><tr><td>Slack</td><td>Configured Slack connection</td><td>Agent connection state, platform permissions, and gateway logs</td></tr><tr><td>WhatsApp linked device</td><td>QR or pairing-code link for each account</td><td>Account is linked; account-specific DM/group policy</td></tr><tr><td>WhatsApp Cloud API</td><td>Business credentials and signed webhook</td><td>Valid signature; DM-only channel</td></tr><tr><td>WeChat</td><td>Personal account linked using QR</td><td>iLink polling and DM allowlist; DM-only channel</td></tr></tbody></table><p>For exact connection fields and routes, see the <a href="https://github.com/0xMaxMa/claude-gateway/blob/main/API.md" target="_blank" rel="noreferrer">channel API reference</a>. These platform checks describe the gateway&#39;s integration behavior; consult the provider&#39;s own console for account setup.</p><h2 id="bring-the-bot-into-a-group" tabindex="-1">Bring the bot into a group <a class="header-anchor" href="#bring-the-bot-into-a-group" aria-label="Permalink to &quot;Bring the bot into a group&quot;">​</a></h2><p>First make sure the platform delivers the message. For Telegram, promote the bot to an admin or disable Privacy Mode and remove/re-add it. A plain message can then initiate group pairing. Bot slash commands are DM-only.</p><p>Approve the group through the gateway&#39;s access controls. With <code>requireMention: true</code>, mention or reply to the bot to trigger a response. Discord also checks the guild allowlist and optional channel/role filters. LINE requires a native mention; typing the name or using <code>@All</code> is insufficient.</p><p>LINE group images/files cannot satisfy its native mention gate. Use a DM or deliberately configure the group to accept messages without a mention. WhatsApp Cloud API and WeChat do not support groups in this integration.</p><p>For the complete access schema and platform limitations, see <a href="https://github.com/0xMaxMa/claude-gateway/blob/main/README.md#channel-conditions--limitations" target="_blank" rel="noreferrer">channel conditions</a>.</p>`,17)])])}const k=t(s,[["render",o]]);export{g as __pageData,k as default};
